struct T {};
void f(const T&) { std::cout << "copy\n"; }
void f(T&&)      { std::cout << "move\n"; }

void wrap(T&& x) {
    f(x);
    f(std::move(x));
}
int main() {
    T t;
    wrap(std::move(t));
    wrap(T{});
}

std::optional<std::string> pending =
    std::string(25, 'o');
void send_pending() {
  if (pending) {
    auto msg = std::move(*pending);
    std::cout << "sent " << msg.size()
              << " bytes\n";
  }
}
int main() { send_pending(); send_pending(); }

void send_pending() {
  if (pending) {
    auto msg = std::move(*pending);
    pending.reset();      // now consumed
    std::cout << "sent " << msg.size()
              << " bytes\n";
  }
}
// prints: sent 25 bytes (once)

